#!/usr/bin/env python3
"""Render research manuscripts with tables generated from the reviewed data bundle."""
import datetime,hashlib,html,json,pathlib,re
ROOT=pathlib.Path(__file__).resolve().parents[1];D=json.loads((ROOT/'data/portrait-series.json').read_text());S={s['id']:s for s in D['sources']};R=D['observations'];I={i['id']:i for i in D['indicators']}
def cite(sid,label=None,locator=None):
 s=S[sid];return '<a href="'+html.escape(s['url'],quote=True)+'">'+html.escape(label or s['title'])+'</a>'+(' ('+html.escape(locator)+')' if locator else '')
def value(id,y):
 rows=[r for r in R if r['indicator_id']==id and r['observation_year']==y and r['value'] is not None]
 return rows[-1]['value'] if rows else None
def fmt(x,d=2):return '—' if x is None else f'{x:,.{d}f}'
def table(ids,years=(2013,2023,2024,2025)):
 out='<div class="table-wrap"><table><thead><tr><th>Indicator / native unit</th>'+''.join(f'<th>{y}</th>' for y in years)+'</tr></thead><tbody>'
 for id in ids:
  i=I[id];out+='<tr><th>'+html.escape(i['label'])+'<small>'+html.escape(i['unit'])+'</small></th>'+''.join('<td>'+fmt(value(id,y))+'</td>' for y in years)+'</tr>'
 return out+'</tbody></table></div><p class="caption">— means no eligible observation, not zero. '+('Gini/equality are H2 urban surveys. Other rows are calendar-year estimates. ' if any(id in ['gini','equality'] for id in ids) else 'Rows are calendar-year estimates. ')+ 'See the data appendix for exact precision, periods and geography.</p>'
def figure(name,caption):
 return '<figure><img src="figures/'+name+'.svg" alt="'+html.escape(caption,quote=True)+'"><figcaption>'+caption+'</figcaption></figure>'
def spaced_body(body):
 out=[]
 for part in re.split(r'(<[^>]+>)',body):
  if part.startswith('<'):out.append(part);continue
  protected=['PM2.5','EPHC-S2','H1','H2','CO2','COVID-19','SDG6.4.2','SDG7']
  for n,t in enumerate(protected):part=part.replace(t,'§'+chr(65+n)+'§')
  part=re.sub(r'(?<=[A-Za-z])(?=\d)|(?<=\d)(?=[A-Za-z])',' ',part)
  part=re.sub(r'(?<=[A-Za-z]),(?=\d)',', ',part)
  part=re.sub(r'(?<=[a-z])\.(?=\d{4}\b)', '. ',part)
  part=re.sub(r'(?<=[A-Za-z%]),(?=[A-Za-z])',', ',part)
  for n,t in enumerate(protected):part=part.replace('§'+chr(65+n)+'§',t)
  out.append(part)
 return ''.join(out)
def shell(title,subtitle,body):
 body=spaced_body(body)
 body=body.replace('columnI','column I').replace('Q 2 2016','Q2 2016')
 return '''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>'''+html.escape(title)+'''</title><style>
:root{color-scheme:light;--ink:#153a42;--muted:#52666b;--line:#d4dfe0;--accent:#087d76;--paper:#fffdf7}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:17px/1.65 Georgia,serif}main{max-width:1040px;padding:60px 44px 90px;margin:auto}header{border-top:7px solid var(--accent);padding-top:28px;margin-bottom:36px}.eyebrow{font:600 12px/1.5 system-ui,sans-serif;letter-spacing:.13em;text-transform:uppercase;color:var(--accent)}h1{font-size:clamp(30px,4.3vw,48px);line-height:1.12;letter-spacing:-.035em;max-width:900px}h2{font-size:26px;line-height:1.3;margin-top:42px}h3{font-size:20px}p{max-width:88ch}a{color:#006b67;text-underline-offset:.15em}small,.caption{font:13px/1.5 system-ui,sans-serif;color:var(--muted)}small{display:block;font-weight:400}.subtitle{font-size:21px;line-height:1.4;color:var(--muted)}.note{padding:18px 23px;background:#eaf3ef;border-left:4px solid var(--accent)}.table-wrap{overflow-x:auto;margin:22px 0}table{border-collapse:collapse;width:100%;font:14px/1.45 system-ui,sans-serif;font-variant-numeric:tabular-nums}th,td{padding:12px 10px;border-bottom:1px solid var(--line);text-align:right;vertical-align:top}th:first-child{text-align:left;min-width:260px}thead th{background:#eaf0ed}tbody th{font-weight:500}.meta,nav{font:14px/1.5 system-ui,sans-serif;color:var(--muted)}code{font:13px ui-monospace,monospace;background:#eef0eb;padding:2px 4px;overflow-wrap:anywhere}li{margin:8px 0}details{border:1px solid var(--line);padding:16px;margin:20px 0}summary{cursor:pointer;font-family:system-ui,sans-serif}footer{border-top:1px solid var(--line);padding-top:24px;margin-top:50px}.page-break{break-before:page}figure{margin:30px 0;break-inside:avoid}figure img{width:100%;height:auto;display:block}.descriptive td{text-align:left}.keep-together{break-inside:avoid}figcaption{font:13px/1.5 system-ui,sans-serif;color:var(--muted);margin-top:12px}@media(max-width:650px){main{padding:24px 20px 50px}h1{font-size:34px}th,td{padding:9px 6px}}@media print{body{font-size:11pt;background:white}main{padding:0;max-width:none}h1{font-size:30pt}h2,h3{break-after:avoid}p{orphans:3;widows:3}tr{break-inside:avoid}table{font-size:8.5pt}figure{margin:20px 0}figcaption{font-size:9pt}nav{display:none}a{color:inherit}.table-wrap{overflow:visible}details{display:block}header{margin-top:0}}</style></head><body><main><header><p class="eyebrow">Research working paper • Evidence cut-off 29 October 2026</p><h1>'''+html.escape(title)+'''</h1><p class="subtitle">'''+html.escape(subtitle)+'''</p><p class="meta">Version 1.0 • Primary-source archive and reproducible data extraction • Working manuscript, not peer reviewed</p><nav><a href="./">Interactive portrait</a> · <a href="argentina-working-paper.html">Argentina paper</a> · <a href="methods-paper.html">Methods paper</a> · <a href="data/portrait-series.json">Data bundle</a> · <a href="data/sources.json">Source archive manifest</a></nav></header>'''+body+'''<footer><p class="caption">Prepared as a descriptive research artifact. Statistical estimates, author projections and policy scenarios retain separate evidentiary status. The source manifest provides exact URLs, archived paths, retrieval times and SHA-256 hashes. No result here identifies the causal effect of an administration or individual policy.</p></footer></main></body></html>'''
body='''<h2>Abstract</h2><p>Argentina’s record around the December 2023 change of administration is mixed across outcomes and sensitive to the comparison period. During 2013–2023, life expectancy, child survival and internet use improved, while real GDP per person was lower at the endpoint and forest cover continued declining. The comparable urban monetary-poverty series does not cover the full decade: the official publication gap prevents an honest 2013-to-2023 comparison. After the inauguration, poverty first rose sharply, then fell substantially, and increased again in the latest semester. Some national ecological accounts extend only to 2023, leaving little or no fully post-inauguration evidence. A partial social Doughnut makes four published benchmarks visible without manufacturing missing dimensions or assigning Argentina an unsupported planetary quota.</p>
<p class="note"><strong>Working scope.</strong> “Rightward shift” is operationalized provisionally as Javier Milei’s inauguration on 10 December 2023, with Mauricio Macri’s 2015 inauguration marked separately. The paper covers the decade 2013–2023 and all eligible released observations since. This is a temporal description, not a test of an ideological proposition.</p>
<h2>1. What a longitudinal country portrait can establish</h2><p>The Doughnut framework asks whether social needs can be met within ecological limits. It does not turn GDP into a comprehensive welfare measure or make a change of government a causal experiment. Fanning and colleagues developed national historical comparisons, whereas Fanning and Raworth’s later global monitor uses a different indicator system and scale. The present paper uses four fixed social benchmarks from the earlier national work and publishes additional outcomes in their original units. It does not relabel global 2000–2022 indicators as Argentina’s national history. '''+cite('fanning2021-paper','Fanning et al.','Table 1 and Methods')+'; '+cite('fanning2025-paper','Fanning and Raworth (2025)','national environmental footprints concern the 2017 comparison')+'''.</p>
<p>The retained benchmarks are life expectancy of 74 years, electricity access of 95%, employment of 94% of the labour force, and equality of 70 points on a scale defined as 100 minus the Gini index. They are published analytical choices, not Argentine legal commitments. Equality is an urban income-survey measure: the World Bank identifies the relevant survey as EPHC-S2 and the reporting coverage as urban. A country-level portrait therefore has mixed geographic coverage, which must remain visible. '''+cite('pip-argentina-all','World Bank PIP survey metadata')+'''.</p>
<h2>2. The preceding decade: progress in capabilities, persistent economic and ecological pressures</h2>'''+table(['life_expectancy','under5_mortality','electricity_access','internet_use','unemployment','gini','gdp_per_capita'])+'''
<p>Life expectancy increased from 75.829 years in 2013 to 77.395 in 2023, a gain of 1.566 years. Under-five mortality declined from 12.7 to 9.7 deaths per 1,000 live births. Internet use rose from 59.90% to 89.23%, an increase of 29.33 percentage points. These are substantial improvements on their respective measures, although internet use does not establish affordability or service quality, and electricity connection does not establish reliable or affordable energy. '''+cite('wdi-SP.DYN.LE00.IN','WDI life expectancy')+'; '+cite('wdi-SH.DYN.MORT','WDI child mortality')+'; '+cite('wdi-IT.NET.USER.ZS','WDI/ITU internet use')+'''.</p>
<p>The decade was not a uniform trend. Life expectancy fell to 73.948 years in 2021 before recovering. Real GDP per capita in constant 2015 US dollars declined from $13,946.10 in 2013 to $12,993.09 in 2023, a 6.83% endpoint decline. ILO-modelled unemployment was 7.10% in 2013, 9.843% in 2019 and 6.139% in 2023. These annual estimates do not describe informal work, hours, labour-force exits or the distribution of earnings. '''+cite('wdi-SP.DYN.LE00.IN','WDI life expectancy')+'; '+cite('wdi-NY.GDP.PCAP.KD','WDI real GDP per capita')+'; '+cite('wdi-SL.UEM.TOTL.ZS','ILO-modelled unemployment via WDI')+'''.</p>
<p>Urban Gini inequality was 41.1 in the 2013 reference survey and 42.4 in the 2023 reference survey. There is no 2015 value in this WDI series. INDEC warns that statistics from the 2007–2015 period require reservations unless explicitly revised, and the post-2016 recovery of statistical production is a substantive break in the evidence base. These facts limit a precise account of the decade; they do not justify substituting guessed poverty values. '''+cite('wdi-SI.POV.GINI','WDI Gini series')+'; '+cite('indec-poverty-fragment','INDEC historical and methodological notice')+'''.</p>
<h2>3. Poverty since the administration change: all available semesters</h2><p>INDEC’s comparable half-year poverty table begins in H2 2016. The survey covers 31 urban agglomerations, rather than every resident of Argentina. Household-income poverty and food-basket indigence use the income and composition of households relative to regional baskets; they are not multidimensional deprivation measures. H2 2023 includes most of the outgoing administration and 21 days of the incoming one. It is an end-2023 reference period rather than a clean untreated baseline. '''+cite('indec-poverty-method','INDEC poverty methods')+'; '+cite('indec-poverty-2026h1-tables','INDEC historical tables','Cuadro 1')+'''.</p>
<div class="table-wrap"><table><thead><tr><th>Observation period</th><th>Poverty, people (%)</th><th>Indigence, people (%)</th></tr></thead><tbody>'''
for y,h in [(2023,1),(2023,2),(2024,1),(2024,2),(2025,1),(2025,2),(2026,1)]:
 def pv(id):return next(r['value'] for r in R if r['indicator_id']==id and r['observation_year']==y and r['period_start'][5:7]==('01' if h==1 else '07'))
 body+=f'<tr><th>{y} H{h}'+(' (provisional)' if y==2026 else '')+f'</th><td>{pv("poverty"):.1f}</td><td>{pv("indigence"):.1f}</td></tr>'
body+='''</tbody></table></div><p class="caption">Source: '''+cite('indec-poverty-2026h1-tables','INDEC historical workbook','Cuadro 1, people rows 7 and 11')+'''. Latest confidence intervals: '''+cite('indec-poverty-2026h1','INDEC H1 2026 technical report','printed p.5, Table 1')+'''.</p>
<p>Relative to H2 2023, H1 2024 poverty rose by 11.2 percentage points, from 41.7% to 52.9%. The subsequent decline reached 28.2% in H2 2025, followed by an increase to 32.3% in H1 2026. Thus, the latest result is 9.4 points below the end-2023 reference, 20.6 points below the H1 2024 peak, and 4.1 points above H2 2025. A season-matched comparison gives 32.3% in H1 2026 versus 40.1% in H1 2023, a decline of 7.8 points. Indigence follows the same broad sequence, from 11.9% in H2 2023 through 18.1%, 8.2%, 6.9%, 6.3% and finally 7.5%.</p>
<p>The latest year-on-year point estimate, 32.3% versus 31.6% in H1 2025, must not be narrated as a statistically established deterioration. INDEC explicitly reports no significant change from the same semester of the preceding year. The 90% confidence intervals for poverty are 30.8–33.7% in H1 2026 and 30.1–33.1% in H1 2025. The within-year increase from H2 2025 is nevertheless part of the published trajectory and cannot be omitted. Confidence-interval overlap alone is not a substitute for the producer’s design-based change test. '''+cite('indec-poverty-2026h1','INDEC H1 2026 report','printed pp.4–5')+'''.</p>
<p>The burden remains uneven: 44.5% of children aged 0–14 were in households below the income poverty line in H1 2026. The report also describes household incomes and regional food and total baskets growing at different rates over the semester. Those accounting relationships explain how the poverty statistic is constructed; this paper does not identify the independent causal contribution of each policy, wage change or price shock. '''+cite('indec-poverty-2026h1','INDEC H1 2026 report','printed p.4 and Table 3.2')+'''.</p>
<h2>4. Stabilization context and remaining social limitations</h2><p>National December-to-December inflation was 211.4% in 2023, 117.8% in 2024 and 31.5% in 2025. The latest month in the archive, September 2026, recorded 1.9% month-on-month inflation and 33.4% year-on-year inflation. These are three different comparison concepts. Falling inflation means slower price increases, not the reversal of the earlier price level. The national CPI series has a December 2016 base; incompatible earlier regional and national-urban indexes are not chained into a fabricated 2013 national history. '''+cite('indec-cpi-historical','INDEC national CPI workbook','national monthly, interannual and index sheets')+'; '+cite('indec-cpi-2026sep','September 2026 CPI report','summary p.3; released 13 October 2026')+'''.</p>
<p>Real GDP per capita declined a further 1.68% in 2024 relative to 2023, then rose to $13,287.12 in 2025. That latest estimate remains 4.73% below 2013. ILO-modelled unemployment was 7.15% in 2024 and 7.145% in 2025, above the 2023 estimate. Urban Gini remained 42.4 at the published one-decimal precision in both 2023 and 2024. None of these outcomes can be inferred from inflation alone. '''+cite('wdi-NY.GDP.PCAP.KD','WDI real GDP per capita')+'; '+cite('wdi-SL.UEM.TOTL.ZS','ILO-modelled unemployment')+'; '+cite('wdi-SI.POV.GINI','WDI Gini')+'''.</p>
<p>Electricity access in the retrieved WDI vintage falls from 100% in 2023 to 98.4% in 2024. The observation is retained, even though both years exceed the selected 95% benchmark. Without a source-level revision and measurement investigation, this paper cannot decide whether the change mainly reflects a substantive change in access, estimation, or input coverage. Deleting an inconvenient value would be equally unjustified. Basic drinking-water and sanitation series in the archived WDI response end in 2016; they provide no current post-2023 assessment. '''+cite('wdi-EG.ELC.ACCS.ZS','WDI electricity access')+'; '+cite('wdi-SH.H2O.BASW.ZS','WDI basic water')+'; '+cite('wdi-SH.STA.BASS.ZS','WDI basic sanitation')+'''.</p>
<h2>5. Ecological outcomes: accounting matters, and so do publication lags</h2>'''+table(['co2_territorial','co2_territorial_per_capita','co2_consumption','co2_consumption_per_capita','forest_area','pm25','renewable_energy','water_stress','material_footprint'])+'''
<p>In the archived preliminary Global Carbon Budget 2025 publisher-site workbook, territorial fossil and cement CO₂ falls from 189.52 Mt in 2013 to 178.41 Mt in 2023, a 5.87% decline, and to 171.06 Mt in 2024, a further 4.12% decline. Derived per-person values fall from 4.451 to 3.918 to 3.743 tonnes, using the same retrieved WDI population vintage. The difference between total and per-person change is material: the 2013–2023 per-person decline is 11.98%. These accounts exclude land-use-change CO₂ and other greenhouse gases. '''+cite('gcb-national-v2025-site','Global Carbon Budget 2025 national workbook','Territorial Emissions, Argentina column I, rows176–187; MtC multiplied by3.664')+'; '+cite('wdi-SP.POP.TOTL','WDI population denominator')+'''.</p>
<p>Consumption-account fossil CO₂, which reallocates trade-embodied emissions, declines from 203.75 Mt in 2013 to 185.67 Mt in 2023. It is higher than territorial emissions in 2023. This accessed preliminary workbook contains no Argentina consumption observation for 2024; that is a limitation of this retrieved vintage, not a claim that no later producer release exists. Consequently, this archived record cannot establish whether the first full year after the inauguration reduced Argentina’s consumption footprint, even though territorial fossil CO₂ declined. The same limitation blocks a claim about an overall national greenhouse-gas footprint. '''+cite('gcb-national-v2025-site','GCB national workbook','Consumption Emissions, Argentina column I, rows33–44')+'''.</p>
<p>Forest area declines from 17.889% of land in 2013 to 17.158% in 2023 and 17.093% in 2024. This is a forest-stock estimate, not a measure of intact biodiversity or of native-forest loss alone. Modelled PM2.5 exposure is 14.60 µg/m³ in 2013 and 14.35 in 2023, with no post-2023 observation in the archive. Renewable energy’s share of total final energy consumption reaches only to 2021 in this WDI series, while the national water-stress series reaches 2022 and repeats the same value, 10.4567%, throughout 2013–2022. Repeated national values do not establish unchanged seasonal or local hydrological conditions. '''+cite('wdi-AG.LND.FRST.ZS','FAO forest area via WDI')+'; '+cite('wdi-EN.ATM.PM25.MC.M3','WDI PM2.5 exposure')+'; '+cite('wdi-EG.FEC.RNEW.ZS','Renewables via WDI')+'; '+cite('wdi-water-stress','FAO water stress via WDI')+'''.</p>
<p>UNEP’s material footprint accounts add an especially consequential limitation. The portal exports values through 2024, but its linked technical annex states that projected components enter from 2020 and that 2019 is the last year suitable for statistical correlation analysis. This archive therefore retains 2020–2024 values as separately labelled source model outputs, not as measured post-Milei outcomes. For the eligible 2013–2019 window, the modelled material footprint is 15.9583 to 15.6574 tonnes per person. Material footprint accounts for upstream extraction associated with final demand; domestic material consumption is a different territorial trade balance. Neither is converted into a fabricated current national planetary boundary. '''+cite('unep-material-argentina-export','UNEP IRP Argentina export')+'; '+cite('unep-material-methods','UNEP technical annex (2024)','printed p.6 and pp.34–35')+'''.</p>
<h2>6. Chronology is necessary context, not causal identification</h2><p>Macri took office in December 2015; an IMF Stand-By Arrangement was approved in June 2018; Alberto Fernández took office in December 2019. The evidence window also includes COVID-19 restrictions and a severe drought documented by the national meteorological service in February 2023. These events span different administrations and plausibly affect economic and social outcomes, but the present data do not isolate their contributions. '''+cite('event-inaugurations','Official presidential roster')+'; '+cite('event-imf-bcra','BCRA agreement history')+'; '+cite('event-covid-arca','Decree297/2020')+'; '+cite('event-drought','SMN February2023 drought bulletin record')+'''.</p>
<p>Milei took office on 10 December 2023. BCRA’s new monetary and exchange framework followed on 12 December, with an announced official exchange rate of 800 pesos per US dollar. Decree70/2023 was published on 21 December and Law27,742 on 8 July 2024. Publication dates are kept distinct from the start of an administration and from any subsequent implementation or judicial modification. The timeline marks these events; it does not assign the entire observed change to them or assume that every provision remained in force. '''+cite('event-milei-inauguration','Chamber of Deputies inauguration record')+'; '+cite('event-bcra2023','BCRA framework announcement')+'; '+cite('event-dnu70-arca','Official Decree70/2023 archive')+'; '+cite('event-bases-normativa','Official Law27,742 text')+'''.</p>
<p>The selected chronology also extends beyond the initial reforms. BCRA announced exchange liberalization and a floating-band regime on11April2025, the same date recorded for a new IMF Extended Fund Facility agreement. A15December2025 BCRA announcement set out changes for2026; the exchange-band regime description confirms an inflation-linked adjustment rule from1January2026. These source documents establish dated policy changes, not a quantitative attribution of the2026 poverty result. The event list is selected context, not an exhaustive inventory of all laws, transfers or fiscal measures. '''+cite('event-bcra2025-bands','BCRA Phase3 announcement')+'; '+cite('event-imf-bcra','BCRA agreement history')+'; '+cite('event-bcra2026-plan','BCRA2026 programme announcement')+'; '+cite('event-bcra-bands-regime','BCRA exchange-band regime')+'''.</p>
<h2>7. Interpretation and a bounded conclusion</h2><p>The data support three distinct statements. First, the pre-2024 decade contained improvements in several capabilities alongside persistent poverty, lower real GDP per person at the endpoints and ecological pressure. Second, the post-inauguration social record includes both the initial poverty spike and a large subsequent decline, with a latest-semester reversal that remains below the end-2023 reference. Third, the environmental evidence is too incomplete and lagged to conclude that Argentina has moved inside a full national Doughnut under the new administration. Territorial emissions and forest cover also move in different directions on the available estimates.</p>
<p>The four-sector benchmark view is deliberately partial. Life expectancy and electricity meet their selected thresholds in 2013, 2023 and 2024; equality falls short in all three; employment falls slightly short in all three and more so in 2024 than 2023. Life expectancy briefly falls below 74 during 2021. These classifications do not mean that energy deprivation disappeared, that income distribution is adequate outside the sampled urban areas, or that all unmeasured social foundations have been achieved. A useful policy assessment should retain each outcome and each missing dimension, rather than declare a winner from one selected endpoint.</p>
<h2>Appendix: published historical reference, kept separate</h2><p>Fanning et al.’s archived Argentina historical sheets report ecological ratios above one for all six retained biophysical indicators in 2013 and 2015. The 2015 ratios are 1.84 for cumulative carbon, 7.47 for phosphorus, 8.10 for nitrogen, 1.78 for land-system pressure, 2.16 for ecological footprint and 2.12 for material footprint. These are publication-specific, normalized estimates, not the modern native-unit series above. Some source “historical” values already use projected or repeated inputs: nitrogen after 2010 and elements of HANPP require explicit caution. The original 2016–2050 BAU sheets are not imported as observations. '''+cite('fanning2021-data','Published supplementary workbook','Biophysical_Historical, Argentina2015')+'; '+cite('fanning2021-methods','Original supplementary methods','nutrient projections and HANPP carry-forward')+'''.</p>
<p>Reproducibility files: <a href="data/portrait-series.json">main bundle</a>, <a href="data/endpoints.json">endpoint audit</a>, <a href="data/published-historical-reference.json">separate historical reference</a>, <a href="data/modeled-reference.json">separate projection-contaminated material outputs</a>, and <a href="data/sources.json">source hashes and exact URLs</a>. The companion <a href="methods-paper.html">methods paper</a> describes admissibility, normalization and the limitations of policy inference.</p>'''
body=body.replace('<h2>2. The preceding decade:',figure('partial-social-doughnuts','Figure 1. A partial social Doughnut in 2013, 2023 and 2024. Green marks a fixed benchmark; red extent and numbers show the shortfall relative to that benchmark, not the share of people deprived. Equality uses urban H2 surveys, with statistical cautions for 2013. The other sectors use national annual estimates. Published thresholds: Fanning et al., Table 1; values: archived WDI/PIP series. No ecological or overall score is implied.')+'<h2>2. The preceding decade:')
body=body.replace('<h2>4. Stabilization context',figure('poverty-history','Figure 2. Income poverty and indigence in the EPH urban sample. Points are period midpoints; horizontal bars show semester coverage. Line gaps preserve missing periods or source coverage changes. Vertical whiskers show source-reported 90% confidence intervals where available. The H1 2026 estimates (*) are provisional. INDEC reports no significant change from H1 2025. Inauguration markers provide chronology, not effect estimates. Source: INDEC historical workbook and H1 2026 report, Table 1.')+'<h2>4. Stabilization context')
body=body.replace('<h2>6. Chronology',figure('ecological-evidence','Figure 3. Ecological evidence in native units, with separate vertical scales and a common time axis. Horizontal bars span each observation year; dashed lines mark 10 December 2023. No ecological boundary is assigned. The material series stops in 2019 because recent source values contain projected inputs. Carbon uses the accessed preliminary GCB 2025 workbook, with WDI population; forest and exposure estimates use WDI; material accounts use UNEP IRP.')+'<h2>6. Chronology')
(ROOT/'argentina-working-paper.html').write_text(shell('Argentina before and after December 2023','A partial longitudinal Doughnut, social outcomes, ecological accounts and the limits of policy attribution',body))
methods='''<h2>Abstract</h2><p>A longitudinal Doughnut can help compare social and ecological outcomes around a policy transition only if it preserves measurement definitions, benchmark choices, data vintages and uncertainty. Argentina provides a demanding example: urban poverty statistics have a publication break, internationally reported inequality refers to second-semester urban surveys, carbon accounts have unequal endpoints, and a material-flow database includes projected inputs in apparently historical recent years. This paper specifies and applies an auditable protocol for a partial country portrait. It produces a four-sector social benchmark view and a separate ecological evidence panel, rather than filling a complete Doughnut with unsupported estimates. Policy dates are represented as chronology. No counterfactual policy effect is estimated.</p>
<h2>1. Research question and unit of analysis</h2><p>The empirical question is how selected social foundations and ecological pressures changed during 2013–2023 and in all eligible released periods after the 10 December 2023 inauguration. Macri’s 2015 inauguration is an independent milestone within the baseline decade. The working temporal interpretation is provisional and can be changed without changing any observation. Neither administration dates nor the phrase “rightward shift” is an outcome variable.</p>
<p>The unit of analysis is an indicator-period-geography-method-vintage combination. “Argentina,2023” alone is insufficient. Life expectancy is a national calendar-year population estimate; poverty is a semester survey estimate for 31 urban agglomerations; the internationally reported Gini is a second-semester urban income survey. Treating all three as a nationally representative annual panel would change the question and overstate comparability. '''+cite('wdi-meta-SP.DYN.LE00.IN','Life-expectancy metadata')+'; '+cite('indec-poverty-2026h1-tables','INDEC half-year table')+'; '+cite('pip-argentina-all','PIP survey-period and coverage metadata')+'''.</p>
<h2>2. Published frameworks and the boundary of this adaptation</h2><p>Fanning et al.’s national historical study covers 1992–2015 and provides 2016–2050 business-as-usual projections. Its spreadsheet is a valuable reference, but a 2023 row in a BAU sheet is a forecast from that earlier analysis, not a subsequently observed 2023 outcome. The present extraction imports only the two original historical sheets into a separate reference artifact, and still notes that some values within those sheets rely on original projected or repeated inputs. Modern data are assembled independently and never spliced into the publication’s normalized ratios. '''+cite('fanning2021-data','Original supplementary data')+'; '+cite('fanning2021-methods','Original supplementary methods','nutrients pp.2–3 and HANPP p.3 in the supplement’s own numbering')+'''.</p>
<p>Fanning and Raworth’s 2025 global monitor uses global time-series indicators over 2000–2022 and a national environmental-footprint comparison for 2017. Its national comparison does not create annual national observations for Argentina. Further, global processes such as atmospheric CO₂ concentration cannot be assigned to a country simply by relabelling a chart. Any allocation of planetary limits requires a stated sharing principle, appropriate footprint accounts and a boundary definition. '''+cite('fanning2025-paper','Fanning and Raworth (2025)','Methods and inequalities sections')+'''.</p>
<p>The current benchmark view therefore retains only four source-supported social sectors, with fixed published thresholds held invariant across modern years. It is a partial country portrait with mixed coverage, not an updated complete national Doughnut. Ecological indicators remain in native units without invented national ceilings. A PM2.5 health-exposure guideline, for example, would be a different kind of benchmark from a national allocation of the planetary aerosol boundary.</p>
<h2>3. Source acquisition and reproducibility</h2><p>Sources are primary statistical tables, official API responses, producer methodological documents, peer-reviewed primary analyses and official legal or institutional records. World Bank WDI is a distribution channel for several upstream producers; two pages reproducing its values are not independent corroboration. GCB consumption and territorial accounts also share a production system and must not be counted as two independent measurements of the same concept.</p>
<p>Every admitted source has an exact requested and resolved URL, publisher, archived relative path, byte count, retrieval timestamp and SHA-256 digest. A release date is recorded when established; unknown release dates remain null. WDI’s API-level last-updated date is recorded separately and is not assigned as the original release date of each historical observation. The archive also preserves unsuccessful ICOS retrievals as access-page evidence, explicitly excluding them from numerical extraction. The successful GCB publisher-site workbook is identified as its own preliminary vintage, rather than pretending to have obtained the inaccessible final ICOS workbook.</p>
<p>The extraction script runs locally against the archived bytes. It parses INDEC XLS tables with xlrd, GCB and published reference XLSX tables with openpyxl, WDI/PIP JSON using native JSON parsing, and UNEP’s CSV export using a CSV parser. It performs no network requests, interpolation, imputation or policy-effect inference. Human-written prose cites these source documents; the exact extracted rows and cells remain machine-readable. The shared application validator independently checks schema, identifiers, period shapes, dates, missing-value reasons, paths and source hashes.</p>
<div class="table-wrap"><table class="descriptive"><thead><tr><th>Artifact</th><th>Purpose</th></tr></thead><tbody>
<tr><th><a href="data/portrait-series.json">portrait-series.json</a></th><td>Versioned main evidence bundle, native units, fixed target metadata, dated events and source references</td></tr>
<tr><th><a href="data/endpoints.json">endpoints.json</a></th><td>First available, last pre-2024 reference and latest eligible observation for each indicator</td></tr>
<tr><th><a href="data/modeled-reference.json">modeled-reference.json</a></th><td>UNEP2020–2024 source outputs containing projected inputs; excluded from empirical history</td></tr>
<tr><th><a href="data/published-historical-reference.json">published-historical-reference.json</a></th><td>Original Argentina1992–2015 normalized publication data, with source-specific methodological caveats</td></tr>
<tr><th><a href="data/sources.json">sources.json</a></th><td>Exact URLs, primary archive paths, release-date gaps, retrieval times and content hashes</td></tr>
<tr><th><a href="scripts/build_dataset.py">build_dataset.py</a></th><td>Deterministic source-table extraction and arithmetic</td></tr>
</tbody></table></div>
<h2>4. Admissibility, epistemic status and missing data</h2><p>An empirical-history value must be a source-supported observation or retrospective statistical estimate for a completed observation period. Survey estimates, demographic models, accounts and satellite-derived estimates are all estimates; the presence of uncertainty does not make them policy forecasts. Each available modern row is labelled <code>retrospective-estimate</code> with status <code>source-supported-observation</code>. Missing rows retain a null value, missing status and explicit reason. Nulls never become zeros.</p>
<p>Projection-contaminated material-flow values are handled differently. UNEP’s linked technical annex says projected components enter from 2020 and recommends 2019 as the last year for correlation analysis. The portal’s 2024 numerical endpoint is therefore not sufficient to admit that value as a measured post-policy outcome. Main material-footprint history ends in 2019; 2020–2024 values are retained separately, labelled as source model outputs with a usage restriction. This is a substantive result of the methods review, not a claim that material use stopped being important. '''+cite('unep-material-methods','UNEP technical annex','printed p.6 and pp.34–35')+'''.</p>
<p>No full-year 2026 observation is manufactured, and no incomplete 2026 year is compared with a completed annual estimate as though they were the same interval. Monthly CPI, semester poverty and annual national accounts retain their own frequencies. A year selector can display a year’s available sectors, but it must show which period and coverage each sector uses and leave unavailable sectors unknown.</p>
<h2>5. Four-sector benchmark mathematics</h2><p>Let <em>x</em> be a social indicator in its native higher-is-better scale, and <em>T</em> its fixed published threshold. This adaptation reports the ratio <code>r=x/T</code> and benchmark-relative shortfall <code>s=max(0,1−r)</code>. A sector meets the benchmark when <code>x≥T</code>. Employment is explicitly <code>100−ILO unemployment</code>; equality is explicitly <code>100−Gini</code>. The four thresholds are74 years,95%,94% and70 points, respectively. None is re-estimated from the selected year’s distribution. '''+cite('fanning2021-paper','Published national benchmarks','Table1')+'''.</p>
<p>This is not the original authors’ social normalization. Their procedure subtracts the lowest globally observed 1992–2015 value before dividing by the distance from that minimum to the threshold. Both procedures classify threshold attainment identically, but shortfall magnitudes differ. The modern benchmark-relative ratios must therefore be labelled as this adaptation’s arithmetic and never joined directly to the archived publication ratios. There is no averaging of social deficits into a welfare score, and no netting of a social improvement against an ecological deterioration. '''+cite('fanning2021-paper','Original normalization','Methods, printed author-manuscript p.10')+'''.</p>
<div class="table-wrap keep-together"><table><thead><tr><th>Sector</th><th>Fixed threshold</th><th>2013 value</th><th>2023 value</th><th>2024 value</th><th>2024 benchmark-relative gap</th></tr></thead><tbody>'''
for id,target in [('life_expectancy',74),('electricity_access',95),('employment',94),('equality',70)]:
 x=value(id,2024);gap=max(0,1-x/target)*100
 methods+='<tr><th>'+html.escape(I[id]['label'])+'</th><td>'+str(target)+'</td>'+''.join('<td>'+fmt(value(id,y),3)+'</td>' for y in [2013,2023,2024])+f'<td>{gap:.3f}% of benchmark</td></tr>'
methods+='''</tbody></table></div><p class="caption">Values in the producer’s native scale. Equality uses H2 urban surveys; other sectors use national calendar-year estimates. A zero gap means the selected benchmark was met, not universal absence of deprivation.</p>
<p>The actual four-sector results illustrate a limitation of the framework view. Both 2023 and 2024 meet the electricity benchmark, although the source estimate declines from100% to98.4%. A binary threshold can hide change above a standard, which is why native values are always displayed. Conversely, urban equality is57.6 points in both years at WDI precision, corresponding to a17.714% benchmark-relative shortfall in this adaptation, while employment’s relative gap rises from0.148% to1.223%. These are transparent index calculations, not percentages of residents deprived.</p>
<h2>6. Geography and statistical-production breaks</h2><p>INDEC stopped publishing the poverty series in H2 2013 and resumed with Q2 2016. That quarter is not silently substituted for H1 2016. The comparable full-semester table begins in H2 2016. The source’s caution about 2007–2015 statistics remains attached to affected earlier inequality reference years. H2 2019 excludes Gran Resistencia, while H2 2020 excludes Ushuaia–Rio Grande; those periods carry their own coverage flags and comparability groups. COVID-era collection changes are also identified. Lines break at missing periods, flagged discontinuities and changes of comparability group. '''+cite('indec-poverty-fragment','INDEC publication and method notice')+'; '+cite('indec-poverty-2026h1-tables','Official historical workbook','Cuadro1 footnotes')+'''.</p>
<p>The World Bank’s “annual” Argentina Gini label is a reporting-year convention. PIP identifies the underlying observation as EPHC-S2, an urban second-semester survey, so the modern bundle represents it as an H2 observation and leaves H1 unknown. WDI’s one-decimal Gini is retained instead of replacing it with PIP’s unrounded value; PIP supplies the period and coverage evidence. This separates revision and rounding choices from geography. '''+cite('pip-argentina-all','PIP source metadata')+'; '+cite('wdi-SI.POV.GINI','WDI published Gini precision')+'''.</p>
<h2>7. Ecological definitions and denominator arithmetic</h2><p>The Global Carbon Budget workbook reports million tonnes of carbon per year. Its specified conversion factor is3.664, so the reproduced fossil CO₂ total is <code>MtCO₂=MtC×3.664</code>. The derived per-person series is <code>tCO₂/person=MtCO₂×10⁶/WDIpopulation</code>, using one retrieved population vintage. Each row records the original workbook cell and population source. No land-use-change emissions or non-CO₂ gases are added or implied. The 2023 territorial and consumption accounts are178.407 and185.666MtCO₂, respectively; only the territorial account has a2024 value in this workbook. '''+cite('gcb-national-v2025-site','GCB workbook','sheet headers and Argentina columnI')+'; '+cite('wdi-SP.POP.TOTL','Population denominator')+'''.</p>
<p>Forest-stock share is not the share of original forest retained, native-forest deforestation, or a biodiversity footprint. PM2.5 is national population-weighted exposure, not a national aerosol-boundary allocation. Water stress is freshwater withdrawal relative to available resources after environmental flow requirements, not a consumption-based water footprint. Renewable final energy is not renewable electricity. Keeping these definitions attached prevents an apparent multidimensional dashboard from comparing different concepts under familiar labels.</p>
<p>Benchmark selection itself has a time dimension. In the original national study, material and other flow boundaries change with global population. Its CO₂ boundary is a country’s population-weighted share of cumulative emissions before the350ppm boundary was crossed, not a fixed annual tonnes-per-person quota. The modern bundle assigns no such quota. Holding a published social threshold fixed is a declared comparison choice; inventing an annual national carbon limit would be an unsupported change of method. '''+cite('fanning2021-methods','National boundary methods','climate section and material-footprint section')+'''.</p>
<h2>8. Descriptive changes and uncertainty</h2><p>For comparable native values, absolute change is <code>Δ=x₁−x₀</code> and relative change is <code>100×(x₁/x₀−1)</code>, when the baseline is nonzero. Percentage-valued rates are reported in percentage points for absolute change. Poverty41.7% to32.3% is a decline of9.4 percentage points, not9.4%. The full semester sequence is displayed to avoid making the 2024 peak the only baseline. Same-semester comparisons are shown alongside adjacent-semester changes to expose seasonality.</p>
<p>INDEC supplies 90% confidence intervals for recent poverty and indigence estimates. The latest poverty point estimate rises0.7 points year-on-year, but the producer reports no statistically significant change. This judgement is cited directly. The methods do not infer significance from rounded point estimates or fabricate confidence intervals for WDI series that do not provide them. Nor do they treat the digits in modelled estimates as a measure of certainty. '''+cite('indec-poverty-2026h1','INDEC uncertainty and change statement','printed pp.4–5')+'''.</p>
<h2>9. What the policy visualization can and cannot show</h2><p>The chronology distinguishes election, inauguration, policy publication and contextual shocks. A decree’s publication is not evidence that every provision was immediately implemented or survived later judicial review. Observation periods are interval marks; a yearly point is not placed on an inauguration date. The drought marker identifies a documented bulletin period rather than inventing a single shock-onset day. Tooltips and accessible tables retain exact dates and source locators.</p>
<p>The visualization may show paths from a policy to an outcome as qualitative hypotheses, but it must identify them as such. It must not draw a numerical projected effect without a specified model, counterfactual, units, horizon and uncertainty. No numeric policy-effect estimates were established in this research. Source projections, such as UNEP’s recent material outputs or the original Doughnut BAU scenario, remain in separate reference artifacts and cannot fill missing outcome data.</p>
<p>A credible causal extension would need a pre-specified treatment definition, relevant anticipation and implementation dates, a defensible counterfactual, stable measurement and enough post-treatment observations. A before/after regression using one country cannot by itself distinguish fiscal changes, monetary and exchange policy, drought recovery, world commodity prices, COVID recovery, demographic changes or concurrent programmes. Cross-country controls would need a documented comparison design and sensitivity checks; an interrupted series would need credible assumptions about underlying trends and concurrent shocks. This paper supplies the measurement foundation for such work, not its unearned conclusions.</p>
<h2>10. Verification, remaining gaps and update protocol</h2><p>The delivered bundle contains26indicators,696period rows and205explicit nulls in its first complete version. Deterministic checks verify source hashes, finite numeric values, unique indicator-period keys and valid references. A separate core-schema review has checked the actual data structure and chronology. Independent source checks reproduced the poverty estimates and confidence intervals, the source-owned significance statement, published benchmark thresholds and normalization, and the material-flow projection cutoff. A separate recomputation checked 221 WDI or derived rows and 52 carbon rows against archived inputs. These checks support this descriptive working manuscript; they do not constitute journal peer review or causal validation.</p>
<p>Unresolved limits are explicit: no comparable2013–2015 poverty history, incomplete post-2023 consumption accounts and air exposure, no current basic-water/sanitation observation in the retrieved WDI series, projected recent material inputs, unresolved interpretation of the2024 electricity revision/decline, and no complete assessment of housing, political voice, gender equality, social support, biodiversity or novel entities. A reported direction of improvement in the measured subset is not proof of overall Doughnut improvement.</p>
<p>An update should add a new dated archive and regenerate the extraction from that vintage, recording any historical revisions. It should never overwrite a missing point with a forecast, silently change the fixed benchmark, or use a new source definition only for the post-period. For a different political turning point, the same observations can be re-windowed while keeping the event chronology, benchmark version and source records intact. The practical contribution is a transparent distinction between what changed, what remains unknown and what would be required to attribute change to policy.</p>'''
methods=methods.replace('<h2>6. Geography',figure('partial-social-doughnuts','Figure 1. The benchmark-relative normalization used here: max(0, 1 − value / fixed benchmark). Red shows shortfall; the green band marks the threshold. Numbers are percentages of the benchmark, not population deprivation rates. This differs from the historical global-minimum normalization in the original publication. Three national annual sectors and one urban H2 sector form a partial view; 2013 equality carries source comparability cautions.')+'<h2>6. Geography')
(ROOT/'methods-paper.html').write_text(shell('Building a defensible longitudinal Doughnut','Measurement, fixed benchmarks, source projections and policy inference: an applied Argentina protocol',methods))
